cypress_script:
describe('Frames Navigation Tests', () => {
  it('should navigate to Nested Frames page', () => {
    cy.visit('https://the-internet.herokuapp.com/frames');
    cy.get('a[href="/nested_frames"]').click();
    cy.url().should('include', '/nested_frames');
  });

  it('should navigate to iFrame page', () => {
    cy.visit('https://the-internet.herokuapp.com/frames');
    cy.get('a[href="/iframe"]').click();
    cy.url().should('include', '/iframe');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Frames Navigation Tests', () => {
  test('should navigate to Nested Frames page', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/frames');
    await page.click('a[href="/nested_frames"]');
    expect(page.url()).toContain('/nested_frames');
  });

  test('should navigate to iFrame page', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/frames');
    await page.click('a[href="/iframe"]');
    expect(page.url()).toContain('/iframe');
  });
});
